CREATE TABLE t1(a INTEGER PRIMARY KEY,b,c,d,e,f,g); WITH RECURSIVE n(a) AS (VALUES(1) UNION ALL SELECT a+1 FROM n WHERE a<99) INSERT INTO t1 SELECT a,CASE WHEN a IN(90,96,99) THEN NULL ELSE a*11 END,CASE WHEN a IN(91,96,99) THEN NULL ELSE ((a+2)/3)*1001 END,CASE WHEN a IN(92,97,99) THEN NULL ELSE CAST(printf('%d.%03d',a,a) AS REAL) END,CASE WHEN a IN(93,97,99) THEN NULL ELSE ((a+2)/3)*100.1 END,CASE WHEN a IN(94,98,99) THEN NULL ELSE substr('abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz',(a%26)+1,9) END,CASE WHEN a IN(95,98,99) THEN NULL ELSE substr('zyxwvutsrqponmlkjihgfedcbazyxwvutsrqponmlkjihgfedcba',2+((a+2)/5),7) END FROM n; CREATE INDEX t1b ON t1(b); CREATE INDEX t1c ON t1(c); CREATE INDEX t1d ON t1(d); CREATE INDEX t1e ON t1(e); CREATE INDEX t1f ON t1(f); CREATE INDEX t1g ON t1(g); DELETE FROM t1 WHERE a IN(90,91,92,97);